function scr_rhythmgame_add_lyric(p, pQs, pQJ = "") {
  pCo("obj_rhythmgame", pa0 => {
    if (pQJ === "") {
      pQJ = pQs;
      pQs = Ti(pQs, "-", "");
      pQs = Ti(pQs, "<", "");
      pQs = Ti(pQs, ">", "");
      pQs = Ti(pQs, "＜", "");
      pQs = Ti(pQs, "＞", "");
      pQs = Ti(pQs, "+", "");
      pQs = Ti(pQs, "＋", "");
    }
    af1(Cc(pa0, "lyric_time"), pa0.lyric_count)[pa0.lyric_count] = p;
    af1(Cc(pa0, "lyrics"), pa0.lyric_count)[pa0.lyric_count] = pQs;
    af1(Cc(pa0, "censored_lyrics"), pa0.lyric_count)[pa0.lyric_count] = pQJ;
    pa0.lyric_count++;
  });
}
Ve(scr_rhythmgame_add_lyric, "scr_rhythmgame_add_lyric");
function scr_rhythmgame_clear_lyric(p) {
  pCo("obj_rhythmgame", pQs => {
    af1(Cc(pQs, "lyric_time"), pQs.lyric_count)[pQs.lyric_count] = p;
    af1(Cc(pQs, "lyrics"), pQs.lyric_count)[pQs.lyric_count] = "";
    af1(Cc(pQs, "censored_lyrics"), pQs.lyric_count)[pQs.lyric_count] = "";
    pQs.lyric_count++;
  });
}
