function scr_itemcheck_pocket(p) {
  this.haveit = 0;
  this.itemcount = 0;
  for (let pQs = 0; pQs < FA.flag[64]; pQs += 1) {
    if (FA.pocketitem[pQs] === p) {
      this.haveit = 1;
    }
    if (FA.pocketitem[pQs] === p) {
      this.itemcount += 1;
    }
  }
  return this.haveit;
}
