function scr_itemget_anytype_text(...p) {
  this.noroom = 0;
  pCW("scr_itemget_anytype").call(this, p[0], p[1]);
  let pQs = "";
  this.itemname = "NULL";
  this.itemtypename = "NULL";
  let pQJ = p[1];
  let pa0 = p[0];
  if (pQJ === "armor") {
    pCW("scr_armorinfo").call(this, pa0);
    this.itemname = this.armornametemp;
    this.itemtypename = "ARMORs";
  } else if (pQJ === "weapon") {
    pCW("scr_weaponinfo").call(this, pa0);
    this.itemname = this.weaponnametemp;
    this.itemtypename = "WEAPONs";
  }
  if (pQJ === "item") {
    pCW("scr_iteminfo").call(this, pa0);
    this.itemname = this.itemnameb;
    this.itemtypename = "ITEMs";
    if (VL(this._pocketed)) {
      this.itemtypename = "STORAGE";
    }
  }
  if (pQJ === "key") {
    pCW("scr_keyiteminfo").call(this, pa0);
    this.itemname = this.tempkeyitemname;
    this.itemtypename = "KEY ITEMs";
  }
  if (pQJ === "money") {
    this.noroom = 0;
    FA.gold += pa0;
    this.itemtypename = "MONEY HOLE";
    this.itemname = String(pa0) + " Dark Dollars";
  }
  if (pQJ === "points") {
    this.noroom = 0;
    af1(Cc(FA, "flag"), 1044)[1044] += pa0;
    if (FA.flag[1044] > 9999) {
      af1(Cc(FA, "flag"), 1044)[1044] = 9999;
    }
    this.itemtypename = "SCORE";
    this.itemname = String(pa0) + " POINTs";
  }
  if (this.noroom === 0) {
    pQs = pCW("stringsetsubloc").call(this, "* (\\cY~1\\cW was added to your \\cY~2\\cW.)", this.itemname, this.itemtypename, "obj_treasure_room_slash_Other_10_gml_76_0");
  } else {
    pQs = pCW("stringsetsubloc").call(this, "* (You have too many \\cY~2\\cW to take \\cY~1\\c0.)", this.itemname, this.itemtypename, "obj_treasure_room_slash_Other_10_gml_83_0");
  }
  if (p.length >= 3) {
    pQs += p[2];
  } else {
    pQs += "/%";
  }
  return pQs;
}
Ve(scr_itemget_anytype_text, "scr_itemget_anytype_text");
